def world_fk(j):
 T=fk(j); T[:3,3]+=T[:3,2]*offset; T[:3,:3]=Rbase@T[:3,:3];T[:3,3]=Rbase@T[:3,3]+tbase
 return T

def ik(p,rot=None,seed=None):
 if seed is None: seed=q.copy()
 def fun(j):
  T=world_fk(j)
  errs=[(T[:3,3]-p)*5]
  if rot is not None: errs.append(Rotation.from_matrix(rot.T@T[:3,:3]).as_rotvec()*.7)
  errs.append((j-seed)*.02)
  return np.concatenate(errs)
 sol=least_squares(fun,seed,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=250)
 print('IK',sol.x.round(4),'pose',world_fk(sol.x)[:3,3].round(4),'err',np.linalg.norm(world_fk(sol.x)[:3,3]-p),flush=True)
 return sol.x

def cart(p,rot=None,n=60,grip=-1,label='cart'):
 return move(ik(np.array(p),rot),n=n,grip=grip,label=label)
